{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Function App does not explicitly disable public network access, leaving it exposed to the internet by default. This increases the attack surface for unauthorized access or DDoS."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Ensure that function apps enables Authentication",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "Authentication is not enabled on the Function App. Without authentication, the functions can be invoked anonymously if they are not protected by other means (like API keys in headers, which are often bypassed or misconfigured), leading to potential data leakage or abuse."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  storage_account_access_key = azurerm_storage_account.function_storage.primary_access_key

  # CKV_AZURE_221: Disable public network access
  https_only = true
  site_config {
    application_stack {
      node_version = "18"
    }
    # CKV_AZURE_221: Explicitly restrict inbound traffic to only allow private endpoints/VNet integration if needed, 
    # but setting ip_restriction with a deny-all rule effectively disables public access unless specific IPs are allowed.
    # A simpler approach for 'disabling public network access' in TF for Functions is often handled via 
    # `public_network_access_enabled = false` if supported by provider version, or using IP restrictions.
    # However, azurerm_linux_function_app supports `public_network_access_enabled` in newer providers.
    # Let's use the standard attribute if available, otherwise rely on IP restrictions.
    # Note: The prompt asks for minimal changes. Adding `public_network_access_enabled = false` is the direct fix for CKV_AZURE_221.
  }

  # CKV_AZURE_221: Disable public network access
  public_network_access_enabled = false

  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }

  # CKV_AZURE_56: Enable Authentication
  auth_settings {
    enabled         = true
    unauthenticated_client_action = "RedirectToLoginPage"
    token_store {
      enabled = true
    }
  }
}",
  "fix_summary": "Added `public_network_access_enabled = false` to disable public network access (CKV_AZURE_221) and added an `auth_settings` block with `enabled = true` to enforce authentication for the Function App (CKV_AZURE_56)."
}
